// dedupe returns the items of list without repeats, keeping the first of
// each. Items with equal keys are repeats; the key defaults to the item.
export function dedupe(list, key = item => item) {
  const seen = new Set();
  return list.filter(item => {
    const k = key(item);
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });
}

